import{_ as o,o as e,c as a,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const b=JSON.parse('{"title":"Jev Cookbook · Jev 决策模型中文教程","description":"","frontmatter":{},"headers":[],"relativePath":"projects/jev-cookbook.md","filePath":"projects/jev-cookbook.md","lastUpdated":1791119045000}'),n={name:"projects/jev-cookbook.md"};function l(d,t,i,s,h,c){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="jev-cookbook-·-jev-决策模型中文教程" tabindex="-1">Jev Cookbook · Jev 决策模型中文教程 <a class="header-anchor" href="#jev-cookbook-·-jev-决策模型中文教程" aria-label="Permalink to &quot;Jev Cookbook · Jev 决策模型中文教程&quot;">​</a></h1><blockquote><p><a href="https://github.com/datawhalechina/jev-cookbook" target="_blank" rel="noreferrer">datawhalechina/jev-cookbook</a> ⭐140 · <a href="https://datawhalechina.github.io/jev-cookbook/" target="_blank" rel="noreferrer">在线阅读</a> · 我的角色：<strong>主笔 / 第一贡献者</strong>（91 commits）</p></blockquote><h2 id="这个项目在做什么" tabindex="-1">这个项目在做什么 <a class="header-anchor" href="#这个项目在做什么" aria-label="Permalink to &quot;这个项目在做什么&quot;">​</a></h2><p>2026 年 9 月，TypeSafe AI（创始人 Diogo Almeida，InstructGPT 与 RLHF 共同发明人之一）发布了业内首个「系统一模型」（System One Model）<strong>Jev</strong>。当 AI 从聊天窗口走进真实应用，它面对的大量环节不是&quot;生成一段话&quot;，而是&quot;做一个可以被程序理解、检查和执行的判断&quot;——Agent 该调用哪个工具、扫雷该揭开哪格、一句话指令对应哪台设备。</p><p>Jev Cookbook 是 Datawhale 社区发起的 Jev 中文开源教程：把抽象的&quot;让 AI 做决定&quot;拆成可以学习、运行和复盘的具体实验。每一章都回答同一个问题——<strong>这个实验在验证什么，观察到了什么，又不能由此推出什么？</strong></p><h2 id="jev-是什么-我的研究综述" tabindex="-1">Jev 是什么（我的研究综述） <a class="header-anchor" href="#jev-是什么-我的研究综述" aria-label="Permalink to &quot;Jev 是什么（我的研究综述）&quot;">​</a></h2><p>写作教程前，我完成了三篇深度研究报告（算法原理、性能基准、工程落地价值），核心结论：</p><ul><li><strong>设计哲学</strong>：主流大模型（GPT、Claude）是依赖长思维链的&quot;系统二&quot;；而生产软件中的分类、路由、意图识别等高频控制流，本质是低延迟的&quot;系统一&quot;直觉判定。Jev 主动放弃自由文本生成，把模型接口限制为 <strong>Choice / Score / Noul</strong> 三类有类型、带概率的决策原语。</li><li><strong>技术栈</strong>：非自回归的硬件感知并行采样架构（状态前缀 KV 复用 + 多问题单次前向并行评估 + 直接读头输出概率分布），配合<strong>校准决策强化学习 RLCD</strong>——基于 Log Loss、Brier Score 等严格评分规则训练，让模型输出的概率具备统计学意义：大量样本下给出 80% 的判定，经验准确率收敛于 80%。</li><li><strong>实测数据</strong>：官方演示单次判断 0.114 秒（对照 GPT-5.6 Terra 为 8.566 秒）；官方四项工作流端到端最高 193.6× 提速、成本降至 1/444.6。⚠️ 这些均为厂商自测——公开点位匹配后的独立换算约为 25.3× 延迟、76× 成本优势；准确率约 67.8%，接近但尚未超过 frontier LLM（约 74%）。</li><li><strong>定位判断</strong>：Jev 不是 GPT 的替代品，而是&quot;可编程判断器 / probabilistic if-statement / agent critic&quot;。最优架构是组合式的：强 LLM 做规划与生成，Jev 做高频判断与路由，确定性代码做计算与执行，低置信度回落到强模型或人工。</li></ul><h2 id="教程结构-11-章-·-5-个阶段" tabindex="-1">教程结构（11 章 · 5 个阶段） <a class="header-anchor" href="#教程结构-11-章-·-5-个阶段" aria-label="Permalink to &quot;教程结构（11 章 · 5 个阶段）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>章节</th><th>内容</th></tr></thead><tbody><tr><td>提出判断题</td><td>1–3 章</td><td>Jev 是什么；State 与 Noul、Choice、Score 三种问题原语；概率如何进入程序控制流</td></tr><tr><td>进入实际任务</td><td>4–5 章</td><td>18 个 Cookbook Notebook 配方（RAG、风险控制、结构化处理）；智能家居意图识别与动作派发</td></tr><tr><td>实验与项目检验</td><td>6–7 章</td><td>模型评测方法（正确率、概率校准、延迟、成本）；12 个游戏与应用项目（贪吃蛇、扫雷、狼人杀、Browser Use、Mario……）</td></tr><tr><td>研究与 Agent</td><td>8–9 章</td><td>Jev-Mem 长期记忆的写入与检索路由；类型化判断接入 Agent 工具路由与安全门</td></tr><tr><td>模型与证据</td><td>10–11 章</td><td>Laya 本地模型的数据构建、训练、校准路线；知识库证据核对与结论范围</td></tr></tbody></table><h2 id="我的工作" tabindex="-1">我的工作 <a class="header-anchor" href="#我的工作" aria-label="Permalink to &quot;我的工作&quot;">​</a></h2><ul><li><p><strong>主笔教程正文</strong>：从开源初心、项目简介到学习指南与实战演示，搭建全书叙事框架</p></li><li><p><strong>理论底座</strong>：撰写 3 篇 Jev 深度研究报告（术语消歧、架构与 RLCD 机制、性能数据置信度分析）</p></li><li><p><strong>组织复现</strong>：拆解 8 个应用复现任务并汇总社区资料上传 GitHub，亲自负责数独与 TypeSafe Mario 真机复现研究（见 <a href="https://github.com/Bald0Wang/jev-playground" target="_blank" rel="noreferrer">jev-playground</a>）</p></li><li><p><a href="/projects/">返回项目总览</a></p></li></ul>',12)])])}const k=o(n,[["render",l]]);export{b as __pageData,k as default};
